'use strict';

// MODULES //

var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isNaNValue = require( '@stdlib/math/base/assert/is-nan' );
var dscal = require( '@stdlib/blas/base/dscal/lib/ndarray.js' ); // eslint-disable-line stdlib/no-internal-require
var dswap = require( '@stdlib/blas/base/dswap/lib/ndarray.js' ); // eslint-disable-line stdlib/no-internal-require


// MAIN //

/**
* Computes the unblocked complete-pivoting Cholesky factorization.
*
* Derived from Reference-LAPACK DPSTF2, pinned at
* 2e5d9c1273435fbd953adb294ed603e4789afaba. The package-local ordered
* GEMV loops retain reference BLAS update order even for row-major views.
* The first-maximum scan compares candidate values, not absolute values.
* See NOTICE for the full BSD terms and reference provenance.
*
* @private
* @param {integer} u - triangle
* @param {integer} N - order
* @param {Float64Array} A - matrix
* @param {integer} ra - row stride
* @param {integer} ca - column stride
* @param {integer} oa - matrix offset
* @param {Int32Array} P - permutation output
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @param {Int32Array} R - rank output
* @param {integer} orank - rank offset
* @param {number} tol - tolerance
* @param {Float64Array} W - scratch
* @param {integer} sw - scratch stride
* @param {integer} ow - scratch offset
* @returns {integer} INFO
*/
function dpstf2(u, N, A, ra, ca, oa, P, sp, op, R, orank, tol, W, sw, ow) { // eslint-disable-line max-params
	var value;
	var stop;
	var temp;
	var ajj;
	var pvt;
	var pos;
	var i;
	var j;
	var k;
	if ((N === 0)) {
		R[orank] = 0;
		return 0;
	}
	for (i = 0; (i < N); i++) {
		P[(op + (i * sp))] = (i + 1);
	}
	pvt = 0;
	ajj = A[oa];
	for (i = 1; (i < N); i++) {
		value = A[((oa + (i * ra)) + (i * ca))];
		if ((value > ajj)) {
			pvt = i;
			ajj = value;
		}
	}
	if (((ajj <= 0) || isNaNValue(ajj))) {
		R[orank] = 0;
		return 1;
	}
	stop = (tol < 0) ? ((N * 1.1102230246251565e-16) * ajj) : tol;
	for (i = 0; (i < N); i++) {
		W[(ow + (i * sw))] = 0;
	}
	for (j = 0; (j < N); j++) {
		for (i = j; (i < N); i++) {
			pos = (ow + (i * sw));
			if ((j > 0)) {
				value = (u === 121) ? A[((oa + ((j - 1) * ra)) + (i * ca))] : A[((oa + (i * ra)) + ((j - 1) * ca))];
				W[pos] += (value * value);
			}
			W[(ow + ((N + i) * sw))] = (A[((oa + (i * ra)) + (i * ca))] - W[pos]);
		}
		if ((j > 0)) {
			pvt = j;
			ajj = W[(ow + ((N + j) * sw))];
			for (i = (j + 1); (i < N); i++) {
				value = W[(ow + ((N + i) * sw))];
				if ((value > ajj)) {
					ajj = value;
					pvt = i;
				}
			}
			if (((ajj <= stop) || isNaNValue(ajj))) {
				A[((oa + (j * ra)) + (j * ca))] = ajj;
				R[orank] = j;
				return 1;
			}
		}
		if ((j !== pvt)) {
			A[((oa + (pvt * ra)) + (pvt * ca))] = A[((oa + (j * ra)) + (j * ca))];
			if ((u === 121)) {
				if ((j > 0)) {
					dswap(j, A, ra, (oa + (j * ca)), A, ra, (oa + (pvt * ca)));
				}
				if ((pvt < (N - 1))) {
					dswap(((N - pvt) - 1), A, ca, ((oa + (j * ra)) + ((pvt + 1) * ca)), A, ca, ((oa + (pvt * ra)) + ((pvt + 1) * ca)));
				}
				if ((((pvt - j) - 1) > 0)) {
					dswap(((pvt - j) - 1), A, ca, ((oa + (j * ra)) + ((j + 1) * ca)), A, ra, ((oa + ((j + 1) * ra)) + (pvt * ca)));
				}
			} else {
				if ((j > 0)) {
					dswap(j, A, ca, (oa + (j * ra)), A, ca, (oa + (pvt * ra)));
				}
				if ((pvt < (N - 1))) {
					dswap(((N - pvt) - 1), A, ra, ((oa + ((pvt + 1) * ra)) + (j * ca)), A, ra, ((oa + ((pvt + 1) * ra)) + (pvt * ca)));
				}
				if ((((pvt - j) - 1) > 0)) {
					dswap(((pvt - j) - 1), A, ra, ((oa + ((j + 1) * ra)) + (j * ca)), A, ca, ((oa + (pvt * ra)) + ((j + 1) * ca)));
				}
			}
			temp = W[(ow + (j * sw))];
			W[(ow + (j * sw))] = W[(ow + (pvt * sw))];
			W[(ow + (pvt * sw))] = temp;
			temp = P[(op + (pvt * sp))];
			P[(op + (pvt * sp))] = P[(op + (j * sp))];
			P[(op + (j * sp))] = temp;
		}
		ajj = sqrt(ajj);
		A[((oa + (j * ra)) + (j * ca))] = ajj;
		if ((j < (N - 1))) {
			if ((u === 121)) {
				// Trans: complete each ascending-row dot before its output update.
				if ((j > 0)) {
					for (i = (j + 1); (i < N); i++) {
						temp = 0;
						for (k = 0; (k < j); k++) { // eslint-disable-line max-depth
							temp += (A[((oa + (k * ra)) + (i * ca))] * A[((oa + (k * ra)) + (j * ca))]);
						}
						A[((oa + (j * ra)) + (i * ca))] += -temp;
					}
				}
				dscal(((N - j) - 1), (1 / ajj), A, ca, ((oa + (j * ra)) + ((j + 1) * ca)));
			} else {
				// NoTrans: unconditional ascending-column scaled additions.
				for (k = 0; (k < j); k++) {
					temp = -A[((oa + (j * ra)) + (k * ca))];
					for (i = (j + 1); (i < N); i++) {
						A[((oa + (i * ra)) + (j * ca))] += (temp * A[((oa + (i * ra)) + (k * ca))]);
					}
				}
				dscal(((N - j) - 1), (1 / ajj), A, ra, ((oa + ((j + 1) * ra)) + (j * ca)));
			}
		}
	}
	R[orank] = N;
	return 0;
}


// EXPORTS //

module.exports = dpstf2;
